#!/usr/bin/env bash
#
# apply_ui_redesign.sh -- applies the front-end layout redesign to the Course Scheduler GUI.
#
# WHAT IT DOES
#   Switches to the branch ui/layout-redesign (creating it from the latest origin/develop
#   only if it does not exist yet) and applies the redesign to it (nothing is committed --
#   you review and test first). The redesign changes only
#   gui/ (templates, stylesheet, one small script); no Python logic is touched.
#
#   * Shared design: one stylesheet with design tokens, header with a status pill
#   * Configuration pages get a sidebar to jump between areas (no more going back
#     to the editor to open the next one)
#   * Configuration Editor is a dashboard: area cards with counts at the top, file
#     actions (save / validate / new / load) side by side below
#   * Faculty, Courses and Class Patterns are card grids; Faculty and Courses also
#     get a search box (needs JavaScript; without it the lists work as before)
#   * Rooms, Labs, Meetings, Patterns and Time Slots: the "Add ..." form moves from
#     the bottom of the page into a collapsible panel at the top (it opens by itself
#     when a submission has errors)
#   * Course / Faculty forms lay short fields out in columns, with a Save bar that
#     stays on screen; add / edit / delete pages use the same card layout
#   * Schedule Viewer and Global Settings are grouped into cards
#
# USAGE
#   bash apply_ui_redesign.sh                  run from anywhere inside your clone
#   bash apply_ui_redesign.sh --test           also run "uv run pytest -q" afterwards
#   bash apply_ui_redesign.sh --branch NAME    use a different branch (an existing one is reused, never recreated)
#   bash apply_ui_redesign.sh --here           apply to the branch you are on (no new branch)
#
#   Keep this file outside the repository (or just don't commit it).
#
# UNDO (before you commit)
#   git checkout -- gui && git clean -fd gui
#   (this only discards the uncommitted redesign; your branch stays as it was)
#
# SAFETY
#   * refuses to run if you have uncommitted changes to tracked files
#   * applies as a patch: if a file it touches changed on develop since this was built,
#     it stops, puts you back where you started, and tells you which file
#   * the embedded patch is checked against a SHA-256 checksum before use
#
set -euo pipefail

BASE_COMMIT="31157cb83a3eb867caa9b2afe912a3294c3de0ed"
PATCH_SHA256="78bc089b13d9d65a616b7305210d2c87a14bcb1d017dbc77f40fdfed5b9a22e8"
BRANCH="ui/layout-redesign"

info() { printf '==> %s\n' "$*"; }
warn() { printf 'warning: %s\n' "$*" >&2; }
die()  { printf 'error: %s\n' "$*" >&2; exit 1; }

USE_BRANCH=1
RUN_TESTS=0
while [ $# -gt 0 ]; do
    case "$1" in
        --branch)
            [ $# -ge 2 ] || die "--branch needs a branch name"
            BRANCH="$2"; shift 2 ;;
        --here)  USE_BRANCH=0; shift ;;
        --test)  RUN_TESTS=1; shift ;;
        -h|--help)
            sed -n '2,/^set -euo/p' "$0" | sed '$d' | sed 's/^# \{0,1\}//'
            exit 0 ;;
        *) die "unknown option: $1 (try --help)" ;;
    esac
done

sha256_of() {
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$1" | cut -d' ' -f1
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$1" | cut -d' ' -f1
    else
        echo "unavailable"
    fi
}

command -v git >/dev/null 2>&1 || die "git is not installed"
ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || die "run this from inside your clone of the project"
cd "$ROOT"
[ -f gui/templates/gui/base.html ] || die "this does not look like the scheduler project (gui/templates/gui/base.html is missing)"
git remote get-url origin >/dev/null 2>&1 || die "this clone has no 'origin' remote"

if ! git diff --quiet HEAD -- 2>/dev/null; then
    die "you have uncommitted changes to tracked files. Commit or stash them first, then run this again."
fi

# -- unpack and verify the embedded patch -------------------------------------
PATCH_FILE=$(mktemp "${TMPDIR:-/tmp}/ui-redesign.XXXXXX")
ERR_FILE=$(mktemp "${TMPDIR:-/tmp}/ui-redesign-err.XXXXXX")
trap 'rm -f "$PATCH_FILE" "$ERR_FILE"' EXIT

sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | sed '1d' | base64 --decode > "$PATCH_FILE" 2>/dev/null \
    || die "could not decode the embedded patch (was this file edited or re-saved?)"
ACTUAL_SHA=$(sha256_of "$PATCH_FILE")
if [ "$ACTUAL_SHA" = "unavailable" ]; then
    warn "no sha256sum/shasum found; skipping the checksum check"
elif [ "$ACTUAL_SHA" != "$PATCH_SHA256" ]; then
    die "the embedded patch is corrupted (checksum mismatch). Download the script again."
fi

# -- get the latest develop and make the branch -------------------------------
START_REF=$(git symbolic-ref --quiet --short HEAD 2>/dev/null || git rev-parse HEAD)

CREATED=0
if [ "$USE_BRANCH" -eq 1 ]; then
    info "Fetching the latest develop from origin..."
    git fetch origin develop || die "could not fetch origin/develop (are you online?)"
    if git rev-parse --verify --quiet "refs/heads/$BRANCH" >/dev/null; then
        info "Branch '$BRANCH' already exists; using it (no new branch is created)."
        if [ "$(git symbolic-ref --quiet --short HEAD 2>/dev/null || true)" != "$BRANCH" ]; then
            git checkout -q "$BRANCH"
        fi
        if ! git merge-base --is-ancestor origin/develop HEAD; then
            [ "$START_REF" = "$BRANCH" ] || git checkout -q "$START_REF"
            die "'$BRANCH' does not contain the latest develop yet. Bring it up to date first:
         git checkout $BRANCH && git merge origin/develop
       then run this script again."
        fi
    else
        info "Creating branch '$BRANCH' from origin/develop..."
        git checkout -q -b "$BRANCH" --no-track origin/develop
        CREATED=1
    fi
else
    info "Applying to the current branch ($START_REF) without switching or creating a branch."
fi

HEAD_NOW=$(git rev-parse HEAD)
if [ "$HEAD_NOW" != "$BASE_COMMIT" ]; then
    info "Note: this was built on develop at ${BASE_COMMIT:0:7}; you are at ${HEAD_NOW:0:7}."
fi

# -- apply (all or nothing) -----------------------------------------------------
if ! git apply --check "$PATCH_FILE" 2> "$ERR_FILE"; then
    cat "$ERR_FILE" >&2
    if [ "$USE_BRANCH" -eq 1 ]; then
        git checkout -q "$START_REF"
        [ "$CREATED" -eq 0 ] || git branch -q -D "$BRANCH"
    fi
    die "the redesign does not apply cleanly on top of your code, so nothing was changed.
       The files listed above were changed after this script was built. Ask for a fresh
       script built on the current develop."
fi
git apply "$PATCH_FILE"

info "Applied the redesign. Changes (not committed):"
git status --short -- gui

TEST_FAILED=0
if [ "$RUN_TESTS" -eq 1 ]; then
    if command -v uv >/dev/null 2>&1; then
        info "Running the test suite (uv run pytest -q)..."
        if uv run pytest -q; then
            info "Tests passed."
        else
            warn "Some tests failed -- see the output above."
            TEST_FAILED=1
        fi
    else
        warn "uv is not installed, so the tests were not run (see https://docs.astral.sh/uv/)."
    fi
fi

cat <<'NEXT'

Next steps
  1. Start the app:      uv run python manage.py runserver
     then open           http://127.0.0.1:8000/
     (hard-refresh the page, Ctrl/Cmd+Shift+R, so the new stylesheet loads)
  2. Run the tests:      uv run pytest
  3. Look at every page in Configuration Editor, Schedule Viewer, and an add / edit /
     delete page for each area. Try a narrow browser window too.
  4. Happy with it?      git add -A gui && git commit
     Not happy?          see UNDO at the top of this script (bash apply_ui_redesign.sh --help)
NEXT

[ "$TEST_FAILED" -eq 0 ] || exit 1
exit 0
__PAYLOAD_BELOW__
